seq = None
with open('region.fasta') as f:
    lines = f.read().split('\n')
seq = ''.join(l.strip() for l in lines[1:] if l.strip())
n=len(seq)
comp={'A':'T','T':'A','G':'C','C':'G'}
def rc(s): return ''.join(comp[c] for c in reversed(s))
stops={'TAA','TAG','TGA'}

def orfs(s):
    res=[]
    for f in range(3):
        i=f
        while i+3<=len(s):
            if s[i:i+3]=='ATG':
                j=i+3
                while j+3<=len(s) and s[j:j+3] not in stops:
                    j+=3
                if j+3<=len(s):
                    res.append((j-i, i, j+3))
            i+=3
    return res

allorf=[(L,'+',a,b) for L,a,b in orfs(seq)] + [(L,'-',a,b) for L,a,b in orfs(rc(seq))]
allorf.sort(reverse=True)
print("Longest ATG->stop ORFs:")
for L,st,a,b in allorf[:5]:
    print(f"  {L} nt ({L//3} aa) strand {st} {a+1}-{b}")
print("\n>100 codons (300nt):", [x for x in allorf if x[0]>=300])

# GC content of repeat vs whole
def gc(s): 
    from collections import Counter
    c=Counter(s); return round((c['G']+c['C'])/len(s),3)
print("GC whole:", gc(seq), " GC of repeat 1855-1934:", gc(seq[1854:1934]))
print("GC of flanks (1-1854, 1935-3000):", gc(seq[:1854]+seq[1934:]))
